namespace fs = std::filesystem;
using std::string;
using std::vector;

namespace {

const string kBanner =
    "/*********************************************************************************/\n"
    "/********** THIS FILE IS GENERATED BY TOUCHGFX DESIGNER, DO NOT MODIFY ***********/\n"
    "/*********************************************************************************/\n";

string upper(string s)
{
    for (char& c : s) c = (char)toupper((unsigned char)c);
    return s;
}

string lower(string s)
{
    for (char& c : s) c = (char)tolower((unsigned char)c);
    return s;
}

string join(const vector<string>& v, const string& sep)
{
    string out;
    for (size_t i = 0; i < v.size(); ++i) out += (i ? sep : "") + v[i];
    return out;
}

int num(const Json& j, const char* key, int def = 0)
{
    auto it = j.find(key);
    return it == j.end() ? def : (int)it->get<double>();
}

double flt(const Json& j, const char* key, double def = 0)
{
    auto it = j.find(key);
    return it == j.end() ? def : it->get<double>();
}

string str(const Json& j, const char* key, const string& def = "")
{
    auto it = j.find(key);
    return it == j.end() ? def : it->get<string>();
}

// 1 -> "1.0f", -0.3 -> "-0.3f"
string f(double v)
{
    char buf[64];
    auto r = std::to_chars(buf, buf + sizeof buf, v);
    string s(buf, r.ptr);
    if (s.find_first_of(".e") == string::npos) s += ".0";
    return s + "f";
}

// Integral coordinates print as ints, others as floats.
string coord(double v)
{
    return v == (long long)v ? std::to_string((long long)v) : f(v);
}

string color(const Json& w, const char* key = "Color")
{
    Json c = w.value(key, Json::object());
    return "touchgfx::Color::getColorFromRGB(" + std::to_string(num(c, "Red")) + ", " +
           std::to_string(num(c, "Green")) + ", " + std::to_string(num(c, "Blue")) + ")";
}

string textId(const string& id) { return "T_" + upper(id); }

// "__generated\\foo_bar.png" -> BITMAP_FOO_BAR_ID (same rule as imageconvert)
string bitmapId(string path)
{
    std::replace(path.begin(), path.end(), '\\', '/');
    if (path.rfind("__generated/", 0) == 0) path = path.substr(12);
    path = path.substr(0, path.rfind('.'));
    for (char& c : path)
        if (!isalnum((unsigned char)c)) c = '_';
    return "BITMAP_" + upper(path) + "_ID";
}

string lineEnding(const string& s)
{
    if (s == "Round") return "touchgfx::Line::ROUND_CAP_ENDING";
    if (s == "Square") return "touchgfx::Line::SQUARE_CAP_ENDING";
    return "touchgfx::Line::BUTT_CAP_ENDING";
}

struct Transition {
    string suffix;    // "NoTransition", "SlideTransitionWest"
    string type;      // "touchgfx::NoTransition", "touchgfx::SlideTransition<WEST>"
    string heapType;  // "touchgfx::NoTransition", "SlideTransition<WEST>"
    string include;   // "touchgfx/transitions/SlideTransition.hpp"
    string comment;   // "with no screen transition"
};

Transition transitionOf(const Json& action)
{
    string kind = str(action, "ScreenTransitionType", "ScreenTransitionNone");
    if (kind == "ScreenTransitionNone" || kind.size() <= 16 || kind.rfind("ScreenTransition", 0) != 0)
        return {"NoTransition", "touchgfx::NoTransition", "touchgfx::NoTransition",
                "touchgfx/transitions/NoTransition.hpp", "with no screen transition"};
    string name = kind.substr(16); // "Slide", "Cover", "Wipe", "Block"
    string dir = str(action, "ScreenTransitionDirection", "East");
    string t = name + "Transition<" + upper(dir) + ">";
    return {name + "Transition" + dir, "touchgfx::" + t, t,
            "touchgfx/transitions/" + name + "Transition.hpp",
            "with screen transition towards " + dir};
}

struct ScreenGen {
    const string painter; // "PainterRGB888"
    GenResult& res;
    vector<string> includes;
    vector<string> members;
    vector<string> buffers;
    bool canvas = false, bitmaps = false, texts = false;

    void include(const string& h)
    {
        if (std::find(includes.begin(), includes.end(), h) == includes.end()) includes.push_back(h);
    }

    void member(const string& type, const string& name) { members.push_back("    " + type + " " + name + ";"); }

    void addPainter(const string& n, const Json& w, vector<string>& l)
    {
        include("touchgfx/widgets/canvas/" + painter + ".hpp");
        member("touchgfx::" + painter, n + "Painter");
        l.push_back(n + "Painter.setColor(" + color(w) + ");");
        l.push_back(n + ".setPainter(" + n + "Painter);");
    }

    void addLine(const string& n, const Json& w, vector<string>& l)
    {
        l.push_back(n + ".setStart(" + coord(flt(w, "StartX")) + ", " + coord(flt(w, "StartY")) + ");");
        l.push_back(n + ".setEnd(" + coord(flt(w, "EndX")) + ", " + coord(flt(w, "EndY")) + ");");
        l.push_back(n + ".setLineWidth(" + coord(flt(w, "LineWidth", 1)) + ");");
        l.push_back(n + ".setLineEndingStyle(" + lineEnding(str(w, "LineEndingStyle")) + ");");
    }

    void addProgressBase(const string& n, const Json& w, vector<string>& l)
    {
        l.push_back(n + ".setXY(" + std::to_string(num(w, "X")) + ", " + std::to_string(num(w, "Y")) + ");");
        l.push_back(n + ".setProgressIndicatorPosition(" + std::to_string(num(w, "IndicatorPositionX")) + ", " +
                    std::to_string(num(w, "IndicatorPositionY")) + ", " +
                    std::to_string(num(w, "IndicatorPositionWidth", num(w, "Width"))) + ", " +
                    std::to_string(num(w, "IndicatorPositionHeight", num(w, "Height"))) + ");");
        l.push_back(n + ".setRange(" + std::to_string(num(w, "ProgressRangeMin")) + ", " +
                    std::to_string(num(w, "ProgressRangeMax")) + ");");
    }

    // Circle uses setArc, CircleProgress setStartEndAngle. Angles in degrees, 0 = up, clockwise.
    void addCircle(const string& n, const Json& w, const string& arc, vector<string>& l)
    {
        l.push_back(n + ".setCenter(" + coord(flt(w, "CenterX")) + ", " + coord(flt(w, "CenterY")) + ");");
        l.push_back(n + ".setRadius(" + coord(flt(w, "Radius")) + ");");
        l.push_back(n + ".setLineWidth(" + coord(flt(w, "LineWidth")) + ");");
        l.push_back(n + "." + arc + "(" + coord(flt(w, "StartAngle")) + ", " + coord(flt(w, "EndAngle", 360)) + ");");
    }

    void addBackground(const string& n, const Json& w, vector<string>& l)
    {
        if (!w.contains("FileNameBackground")) return;
        bitmaps = true;
        l.push_back(n + ".setBackground(touchgfx::Bitmap(" + bitmapId(str(w, "FileNameBackground")) + "));");
        // setBackground resizes the widget to the bitmap; keep the designed size like the canvas shows it
        if (w.contains("Width") && w.contains("Height"))
            l.push_back(n + ".setWidthHeight(" + std::to_string(num(w, "Width")) + ", " +
                        std::to_string(num(w, "Height")) + ");");
    }

    string position(const string& n, const Json& w)
    {
        return n + ".setPosition(" + std::to_string(num(w, "X")) + ", " + std::to_string(num(w, "Y")) + ", " +
               std::to_string(num(w, "Width")) + ", " + std::to_string(num(w, "Height")) + ");";
    }

    // Returns the constructor block for one widget, `parent` is "" for the screen itself.
    string widget(const Json& w, const string& parent)
    {
        const string type = str(w, "Type"), n = str(w, "Name");
        vector<string> l;

        if (type == "Box") {
            include("touchgfx/widgets/Box.hpp");
            member("touchgfx::Box", n);
            l.push_back(position(n, w));
            l.push_back(n + ".setColor(" + color(w) + ");");
        } else if (type == "Image") {
            include("touchgfx/widgets/Image.hpp");
            member("touchgfx::Image", n);
            bitmaps = true;
            l.push_back(n + ".setXY(" + std::to_string(num(w, "X")) + ", " + std::to_string(num(w, "Y")) + ");");
            l.push_back(n + ".setBitmap(touchgfx::Bitmap(" + bitmapId(str(w, "RelativeFilename")) + "));");
        } else if (type == "Container") {
            include("touchgfx/containers/Container.hpp");
            member("touchgfx::Container", n);
            vector<string> kids;
            for (const Json& c : w.value("Components", Json::array())) {
                string b = widget(c, n);
                if (!b.empty()) kids.push_back(b);
            }
            string block = "    " + position(n, w) + "\n" + join(kids, "\n\n");
            // ponytail: placement of setVisible for containers not verified against Designer output
            if (!w.value("Visible", true)) block += (kids.empty() ? "" : "\n") + string("    ") + n + ".setVisible(false);";
            return block + (kids.empty() ? "" : "\n\n") + "    " + (parent.empty() ? "" : parent + ".") + "add(" + n + ");";
        } else if (type == "Shape") {
            const Json pts = w.value("Points", Json::array());
            include("touchgfx/widgets/canvas/Shape.hpp");
            member("touchgfx::Shape<" + std::to_string(pts.size()) + ">", n);
            canvas = true;
            l.push_back(position(n, w));
            l.push_back(n + ".setOrigin(" + f(flt(w, "XOrigin")) + ", " + f(flt(w, "YOrigin")) + ");");
            l.push_back(n + ".setScale(" + f(flt(w, "XScale", 1)) + ", " + f(flt(w, "YScale", 1)) + ");");
            l.push_back(n + ".setAngle(" + f(flt(w, "Angle")) + ");");
            addPainter(n, w, l);
            vector<string> p;
            for (const Json& pt : pts) p.push_back("{ " + f(flt(pt, "X")) + ", " + f(flt(pt, "Y")) + " }");
            l.push_back("const touchgfx::AbstractShape::ShapePoint<float> " + n + "Points[" + std::to_string(pts.size()) +
                        "] = { " + join(p, ", ") + " };");
            l.push_back(n + ".setShape(" + n + "Points);");
        } else if (type == "Line") {
            include("touchgfx/widgets/canvas/Line.hpp");
            member("touchgfx::Line", n);
            canvas = true;
            l.push_back(position(n, w));
            addPainter(n, w, l);
            addLine(n, w, l);
        } else if (type == "TextArea") {
            texts = true;
            l.push_back(w.value("AutoSize", false)
                            ? n + ".setXY(" + std::to_string(num(w, "X")) + ", " + std::to_string(num(w, "Y")) + ");"
                            : position(n, w));
            l.push_back(n + ".setColor(" + color(w) + ");");
            l.push_back(n + ".setLinespacing(" + std::to_string(num(w, "LineSpacing")) + ");");
            if (w.contains("Wildcard2")) res.warnings.push_back(n + ": two wildcards not supported");
            if (w.contains("Wildcard1")) {
                include("touchgfx/widgets/TextAreaWithWildcard.hpp");
                member("touchgfx::TextAreaWithOneWildcard", n);
                const Json& wc = w["Wildcard1"];
                const string size = upper(n) + "_SIZE", buf = n + "Buffer";
                buffers.push_back("    static const uint16_t " + size + " = " + std::to_string(num(wc, "BufferSize", 10)) + ";");
                buffers.push_back("    touchgfx::Unicode::UnicodeChar " + buf + "[" + size + "];");
                if (wc.contains("TextId"))
                    l.push_back("Unicode::snprintf(" + buf + ", " + size + ", \"%s\", touchgfx::TypedText(" +
                                textId(str(wc, "TextId")) + ").getText());");
                else
                    l.push_back(buf + "[0] = 0;"); // ponytail: guessed, no golden sample of an empty wildcard yet
                l.push_back(n + ".setWildcard(" + buf + ");");
            } else {
                include("touchgfx/widgets/TextArea.hpp");
                member("touchgfx::TextArea", n);
            }
            l.push_back(n + ".setTypedText(touchgfx::TypedText(" + textId(str(w, "TextId")) + "));");
        } else if (type == "BoxProgress") {
            include("touchgfx/containers/progress_indicators/BoxProgress.hpp");
            member("touchgfx::BoxProgress", n);
            addProgressBase(n, w, l);
            l.push_back(n + ".setDirection(touchgfx::AbstractDirectionProgress::" + upper(str(w, "Direction", "Right")) + ");");
            addBackground(n, w, l);
            l.push_back(n + ".setColor(" + color(w) + ");");
            l.push_back(n + ".setValue(" + std::to_string(num(w, "ProgressInitialValue")) + ");");
        } else if (type == "LineProgress") {
            include("touchgfx/containers/progress_indicators/LineProgress.hpp");
            member("touchgfx::LineProgress", n);
            canvas = true;
            addProgressBase(n, w, l);
            addBackground(n, w, l);
            addPainter(n, w, l);
            addLine(n, w, l);
            l.push_back(n + ".setValue(" + std::to_string(num(w, "ProgressInitialValue")) + ");");
        // ponytail: types below are written from the framework API, no Designer golden sample to compare
        } else if (type == "BoxWithBorder") {
            include("touchgfx/widgets/BoxWithBorder.hpp");
            member("touchgfx::BoxWithBorder", n);
            l.push_back(position(n, w));
            l.push_back(n + ".setColor(" + color(w) + ");");
            l.push_back(n + ".setBorderColor(" + color(w, "BorderColor") + ");");
            l.push_back(n + ".setBorderSize(" + std::to_string(num(w, "BorderSize")) + ");");
        } else if (type == "Circle") {
            include("touchgfx/widgets/canvas/Circle.hpp");
            member("touchgfx::Circle", n);
            canvas = true;
            l.push_back(position(n, w));
            addCircle(n, w, "setArc", l);
            addPainter(n, w, l);
        } else if (type == "CircleProgress") {
            include("touchgfx/containers/progress_indicators/CircleProgress.hpp");
            member("touchgfx::CircleProgress", n);
            canvas = true;
            addProgressBase(n, w, l);
            addCircle(n, w, "setStartEndAngle", l);
            addBackground(n, w, l);
            addPainter(n, w, l);
            l.push_back(n + ".setValue(" + std::to_string(num(w, "ProgressInitialValue")) + ");");
        } else if (type == "ImageProgress") {
            include("touchgfx/containers/progress_indicators/ImageProgress.hpp");
            member("touchgfx::ImageProgress", n);
            bitmaps = true;
            addProgressBase(n, w, l);
            l.push_back(n + ".setDirection(touchgfx::AbstractDirectionProgress::" + upper(str(w, "Direction", "Right")) + ");");
            addBackground(n, w, l);
            l.push_back(n + ".setBitmap(" + bitmapId(str(w, "FileNameImage")) + ");");
            l.push_back(n + ".setValue(" + std::to_string(num(w, "ProgressInitialValue")) + ");");
        } else if (type == "TextProgress") {
            include("touchgfx/containers/progress_indicators/TextProgress.hpp");
            member("touchgfx::TextProgress", n);
            texts = true;
            addProgressBase(n, w, l);
            addBackground(n, w, l);
            l.push_back(n + ".setColor(" + color(w) + ");");
            l.push_back(n + ".setNumberOfDecimals(" + std::to_string(num(w, "NumberOfDecimals")) + ");");
            l.push_back(n + ".setTypedText(touchgfx::TypedText(" + textId(str(w, "TextId")) + "));");
            l.push_back(n + ".setValue(" + std::to_string(num(w, "ProgressInitialValue")) + ");");
        } else {
            res.warnings.push_back(n + ": widget type " + type + " not supported, skipped");
            return "";
        }

        if (w.contains("Alpha")) l.push_back(n + ".setAlpha(" + std::to_string(num(w, "Alpha")) + ");");
        if (!w.value("Visible", true)) l.push_back(n + ".setVisible(false);");
        l.push_back((parent.empty() ? "" : parent + ".") + "add(" + n + ");");
        return "    " + join(l, "\n    ");
    }
};

struct Screen {
    string name;
    vector<Transition> transitions; // incoming, in discovery order
};

// `order` collects every transition type in discovery order, for the FrontendHeap type list.
void addTransition(vector<Screen>& screens, vector<Transition>& order, const string& target, const Transition& t)
{
    if (std::none_of(order.begin(), order.end(), [&](const Transition& e) { return e.heapType == t.heapType; }))
        order.push_back(t);
    for (Screen& s : screens) {
        if (s.name != target) continue;
        for (const Transition& e : s.transitions)
            if (e.suffix == t.suffix) return;
        s.transitions.push_back(t);
    }
}

string screenHeader(const Json& s, ScreenGen& g, bool keys)
{
    const string n = str(s, "Name"), cls = n + "ViewBase", guard = upper(cls) + "_HPP";
    std::ostringstream o;
    o << kBanner << "#ifndef " << guard << "\n#define " << guard << "\n\n"
      << "#include <gui/common/FrontendApplication.hpp>\n#include <mvp/View.hpp>\n"
      << "#include <gui/" << lower(n) << "_screen/" << n << "Presenter.hpp>\n";
    for (const string& h : g.includes) o << "#include <" << h << ">\n";
    o << "\nclass " << cls << " : public touchgfx::View<" << n << "Presenter>\n{\npublic:\n"
      << "    " << cls << "();\n    virtual ~" << cls << "();\n    virtual void setupScreen();\n";
    if (keys) o << "    virtual void handleKeyEvent(uint8_t key);\n";
    o << "\nprotected:\n    FrontendApplication& application() {\n"
      << "        return *static_cast<FrontendApplication*>(touchgfx::Application::getInstance());\n    }\n\n"
      << "    /*\n     * Member Declarations\n     */\n" << join(g.members, "\n") << "\n\n";
    if (!g.buffers.empty())
        o << "    /*\n     * Wildcard Buffers\n     */\n" << join(g.buffers, "\n") << "\n\n";
    o << "private:\n\n";
    if (g.canvas)
        o << "    /*\n     * Canvas Buffer Size\n     */\n    static const uint32_t CANVAS_BUFFER_SIZE = "
          << num(s, "CanvasBufferSize", 7200) << ";\n    uint8_t canvasBuffer[CANVAS_BUFFER_SIZE];\n\n";
    o << "};\n\n#endif // " << guard << "\n";
    return o.str();
}

void screenFiles(const Json& app, const Json& s, vector<Screen>& screens, vector<Transition>& order, GenResult& res)
{
    const string n = str(s, "Name"), cls = n + "ViewBase", dir = lower(n) + "_screen";
    const Json& resolution = app["Resolution"];
    const int bpp = num(app, "SelectedColorDepth", 16);
    ScreenGen g{bpp == 16 ? "PainterRGB565" : bpp == 24 ? "PainterRGB888" : "PainterARGB8888", res};

    Json background = {{"Type", "Box"}, {"Name", "__background"},
                       {"Width", num(resolution, "Width")}, {"Height", num(resolution, "Height")}};
    vector<string> blocks{g.widget(background, "")};
    for (const Json& w : s.value("Components", Json::array())) {
        string b = g.widget(w, "");
        if (!b.empty()) blocks.push_back(b);
    }

    vector<string> keyBlocks;
    for (const Json& i : s.value("Interactions", Json::array())) {
        const Json trig = i.value("Trigger", Json::object());
        const Json act = i.value("Action", Json::object());
        if (str(trig, "Type") != "TriggerPhysicalButtonClicked" || str(act, "Type") != "ActionGotoScreen") {
            res.warnings.push_back(n + "/" + str(i, "InteractionName") + ": " + str(trig, "Type") + " -> " +
                                   str(act, "Type") + " not supported, skipped");
            continue;
        }
        const string key = std::to_string(num(trig, "ButtonKey")), target = str(act, "ActionComponent");
        Transition t = transitionOf(act);
        addTransition(screens, order, target, t);
        keyBlocks.push_back("    if(" + key + " == key)\n    {\n        //" + str(i, "InteractionName") +
                            "\n        //When hardware button " + key + " clicked change screen to " + target +
                            "\n        //Go to " + target + " " + t.comment + "\n        application().goto" + target +
                            "Screen" + t.suffix + "();\n    \n    }");
    }

    std::ostringstream c;
    c << kBanner << "#include <gui_generated/" << dir << "/" << cls << ".hpp>\n";
    if (g.canvas) c << "#include <touchgfx/canvas_widget_renderer/CanvasWidgetRenderer.hpp>\n";
    c << "#include <touchgfx/Color.hpp>\n";
    if (g.bitmaps) c << "#include <images/BitmapDatabase.hpp>\n";
    if (g.texts) c << "#include <texts/TextKeysAndLanguages.hpp>\n";
    c << "\n" << cls << "::" << cls << "()\n{\n";
    if (g.canvas) c << "    touchgfx::CanvasWidgetRenderer::setupBuffer(canvasBuffer, CANVAS_BUFFER_SIZE);\n\n";
    c << join(blocks, "\n\n") << "\n}\n\n" << cls << "::~" << cls << "()\n{\n"
      << (g.canvas ? "    touchgfx::CanvasWidgetRenderer::resetBuffer();\n" : "\n") << "}\n\n"
      << "void " << cls << "::setupScreen()\n{\n\n}\n";
    if (!keyBlocks.empty())
        c << "\nvoid " << cls << "::handleKeyEvent(uint8_t key)\n{\n" << join(keyBlocks, "\n\n") << "\n}\n";

    res.files["generated/gui_generated/include/gui_generated/" + dir + "/" + cls + ".hpp"] =
        screenHeader(s, g, !keyBlocks.empty());
    res.files["generated/gui_generated/src/" + dir + "/" + cls + ".cpp"] = c.str();
}

string typeList(const vector<string>& items, const string& name)
{
    string o;
    for (size_t i = 0; i < items.size(); ++i)
        o += (i ? "            " : "    typedef ") + string("touchgfx::meta::TypeList< ") + items[i] + ",\n";
    o += "            touchgfx::meta::Nil";
    for (size_t i = 1; i < items.size(); ++i) o += " >";
    return o + "\n            > " + name + ";\n";
}

void commonFiles(const Json& app, const vector<Screen>& screens, const vector<Transition>& order, GenResult& res)
{
    const string start = str(app, "StartupScreenName");
    const int bpp = num(app, "SelectedColorDepth", 16);
    const string lcd = "LCD" + std::to_string(bpp) + "bpp";
    const string landscape = str(app, "DisplayOrientation", "Landscape") == "Landscape" ? "LANDSCAPE" : "PORTRAIT";

    vector<string> pub, prot, impls, viewIncludes, views, presenters, heapTransitions, heapIncludes;
    for (const Transition& t : order) {
        heapTransitions.push_back(t.heapType);
        if (std::find(heapIncludes.begin(), heapIncludes.end(), t.include) == heapIncludes.end())
            heapIncludes.push_back(t.include);
    }
    for (const Screen& s : screens) {
        const string& n = s.name;
        viewIncludes.push_back("#include <gui/" + lower(n) + "_screen/" + n + "View.hpp>\n#include <gui/" + lower(n) +
                               "_screen/" + n + "Presenter.hpp>");
        views.push_back(n + "View");
        presenters.push_back(n + "Presenter");
        if (s.transitions.empty()) continue; // ponytail: unreachable screen, Designer output for it unverified
        vector<string> p, q, im;
        for (const Transition& t : s.transitions) {
            const string fn = "goto" + n + "Screen" + t.suffix;
            p.push_back("    void " + fn + "();");
            q.push_back("    void " + fn + "Impl();");
            im.push_back("void FrontendApplicationBase::" + fn + "()\n{\n    transitionCallback = touchgfx::Callback<"
                         "FrontendApplicationBase>(this, &FrontendApplicationBase::" + fn + "Impl);\n"
                         "    pendingScreenTransitionCallback = &transitionCallback;\n}\n\n"
                         "void FrontendApplicationBase::" + fn + "Impl()\n{\n    touchgfx::makeTransition<" + n + "View, " +
                         n + "Presenter, " + t.type + ", Model >(&currentScreen, &currentPresenter, frontendHeap, "
                         "&currentTransition, &model);\n}");
        }
        pub.push_back("    // " + n + "\n" + join(p, "\n\n"));
        prot.push_back("    // " + n + "\n" + join(q, "\n\n"));
        impls.push_back("// " + n + "\n\n" + join(im, "\n\n"));
    }

    std::ostringstream h;
    h << kBanner << "#ifndef FRONTENDAPPLICATIONBASE_HPP\n#define FRONTENDAPPLICATIONBASE_HPP\n\n"
      << "#include <mvp/MVPApplication.hpp>\n#include <gui/model/Model.hpp>\n\nclass FrontendHeap;\n\n"
      << "class FrontendApplicationBase : public touchgfx::MVPApplication\n{\npublic:\n"
      << "    FrontendApplicationBase(Model& m, FrontendHeap& heap);\n    virtual ~FrontendApplicationBase() { }\n\n"
      << "    virtual void changeToStartScreen()\n    {\n        goto" << start << "ScreenNoTransition();\n    }\n\n"
      << join(pub, "\n\n") << "\n\nprotected:\n"
      << "    touchgfx::Callback<FrontendApplicationBase> transitionCallback;\n"
      << "    FrontendHeap& frontendHeap;\n    Model& model;\n\n"
      << join(prot, "\n\n") << "\n};\n\n#endif // FRONTENDAPPLICATIONBASE_HPP\n";
    res.files["generated/gui_generated/include/gui_generated/common/FrontendApplicationBase.hpp"] = h.str();

    std::ostringstream c;
    c << kBanner << "#include <new>\n#include <gui_generated/common/FrontendApplicationBase.hpp>\n"
      << "#include <gui/common/FrontendHeap.hpp>\n#include <touchgfx/transitions/NoTransition.hpp>\n"
      << "#include <texts/TextKeysAndLanguages.hpp>\n#include <touchgfx/Texts.hpp>\n#include <touchgfx/hal/HAL.hpp>\n"
      << "#ifdef SIMULATOR\n#include <platform/driver/lcd/" << lcd << ".hpp>\n#endif\n"
      << join(viewIncludes, "\n") << "\n\nusing namespace touchgfx;\n\n"
      << "FrontendApplicationBase::FrontendApplicationBase(Model& m, FrontendHeap& heap)\n"
      << "    : touchgfx::MVPApplication(),\n      transitionCallback(),\n      frontendHeap(heap),\n      model(m)\n{\n"
      << "    touchgfx::HAL::getInstance()->setDisplayOrientation(touchgfx::ORIENTATION_" << landscape << ");\n"
      << "    touchgfx::Texts::setLanguage(" << str(app, "SelectedStartupLanguage", "GB") << ");\n"
      // ponytail: these three match ART12_DASH (24 bpp, L8 compression); derive from application.config when a project differs
      << "#ifdef SIMULATOR\n"
      << "    reinterpret_cast<touchgfx::" << lcd << "&>(touchgfx::HAL::lcd()).enableTextureMapperAll();\n"
      << "    reinterpret_cast<touchgfx::" << lcd << "&>(touchgfx::HAL::lcd()).enableDecompressorL8_All();\n"
      << "    reinterpret_cast<touchgfx::" << lcd << "&>(touchgfx::HAL::lcd()).enableDecompressorRGB();\n"
      << "#endif\n}\n\n/*\n * Screen Transition Declarations\n */\n\n" << join(impls, "\n\n") << "\n";
    res.files["generated/gui_generated/src/common/FrontendApplicationBase.cpp"] = c.str();

    std::ostringstream hp;
    hp << kBanner << "#ifndef FRONTENDHEAPBASE_HPP\n#define FRONTENDHEAPBASE_HPP\n\n"
       << "#include <common/Meta.hpp>\n#include <common/Partition.hpp>\n#include <mvp/MVPHeap.hpp>\n\n";
    for (const string& i : heapIncludes) hp << "#include <" << i << ">\n";
    hp << "\n#include <gui/common/FrontendApplication.hpp>\n#include <gui/model/Model.hpp>\n\n"
       << join(viewIncludes, "\n") << "\n\n\n"
       << "/**\n"
          " * This class provides the memory that shall be used for memory allocations\n"
          " * in the frontend. A single instance of the FrontendHeap is allocated once (in heap\n"
          " * memory), and all other frontend objects such as views, presenters and data model are\n"
          " * allocated within the scope of this FrontendHeap. As such, the RAM usage of the entire\n"
          " * user interface is sizeof(FrontendHeap).\n"
          " *\n"
          " * @note The FrontendHeap reserves memory for the most memory-consuming presenter and\n"
          " * view only. The largest of these classes are determined at compile-time using template\n"
          " * magic. As such, it is important to add all presenters, views and transitions to the\n"
          " * type lists in this class.\n"
          " *\n"
          " */\n"
       << "class FrontendHeapBase : public touchgfx::MVPHeap\n{\npublic:\n"
       << "    /**\n     * A list of all view types. Must end with meta::Nil.\n"
       << "     * @note All view types used in the application MUST be added to this list!\n     */\n"
       << typeList(views, "GeneratedViewTypes")
       << "\n    /**\n     * Determine (compile time) the View type of largest size.\n     */\n"
       << "    typedef touchgfx::meta::select_type_maxsize< GeneratedViewTypes >::type MaxGeneratedViewType;\n\n"
       << "    /**\n     * A list of all presenter types. Must end with meta::Nil.\n"
       << "     * @note All presenter types used in the application MUST be added to this list!\n     */\n"
       << typeList(presenters, "GeneratedPresenterTypes")
       << "\n    /**\n     * Determine (compile time) the Presenter type of largest size.\n     */\n"
       << "    typedef touchgfx::meta::select_type_maxsize< GeneratedPresenterTypes >::type MaxGeneratedPresenterType;\n\n"
       << "    /**\n     * A list of all transition types. Must end with meta::Nil.\n"
       << "     * @note All transition types used in the application MUST be added to this list!\n     */\n"
       << typeList(heapTransitions, "GeneratedTransitionTypes")
       << "\n    /**\n     * Determine (compile time) the Transition type of largest size.\n     */\n"
       << "    typedef touchgfx::meta::select_type_maxsize< GeneratedTransitionTypes >::type MaxGeneratedTransitionType;\n\n"
       << "    virtual void gotoStartScreen(FrontendApplication& app)\n    {\n        app.goto" << start
       << "ScreenNoTransition();\n    }\nprotected:\n"
       << "    FrontendHeapBase(touchgfx::AbstractPartition& presenters, touchgfx::AbstractPartition& views, "
          "touchgfx::AbstractPartition& transitions, FrontendApplication& app)\n"
       << "        : MVPHeap(presenters, views, transitions, app)\n    {\n\n    }\n\n};\n\n#endif // FRONTENDHEAPBASE_HPP\n";
    res.files["generated/gui_generated/include/gui_generated/common/FrontendHeapBase.hpp"] = hp.str();

    const Json& r = app["Resolution"];
    res.files["generated/gui_generated/include/gui_generated/common/SimConstants.hpp"] =
        kBanner + "#ifndef SIMCONSTANTS_HPP\n#define SIMCONSTANTS_HPP\n\nstatic unsigned short SIM_WIDTH = " +
        std::to_string(num(r, "Width")) + ";\nstatic unsigned short SIM_HEIGHT = " + std::to_string(num(r, "Height")) +
        ";\n#define SIM_TITLE \"" + str(app, "Name") + "\"\n\n#endif // SIMCONSTANTS_HPP\n";
}

} // namespace

GenResult generate(const Json& project)
{
    GenResult res;
    const Json& app = project["Application"];
    if (!app.value("CustomContainerDefinitions", Json::array()).empty())
        res.warnings.push_back("custom containers not supported yet");

    vector<Screen> screens;
    vector<Transition> order;
    for (const Json& s : app["Screens"]) screens.push_back({str(s, "Name"), {}});
    addTransition(screens, order, str(app, "StartupScreenName"), transitionOf(Json::object()));
    for (const Json& s : app["Screens"]) screenFiles(app, s, screens, order, res);
    commonFiles(app, screens, order, res);
    return res;
}

int writeFiles(const string& touchgfxDir, const GenResult& r)
{
    int written = 0;
    for (const auto& [rel, content] : r.files) {
        fs::path p = fs::path(touchgfxDir) / rel;
        std::ifstream in(p, std::ios::binary);
        std::stringstream old;
        old << in.rdbuf();
        if (in && old.str() == content) continue;
        fs::create_directories(p.parent_path());
        std::ofstream(p, std::ios::binary) << content;
        ++written;
    }
    // Screens that no longer exist: their *_screen folders would still compile and fail.
    for (const char* sub : {"generated/gui_generated/include/gui_generated", "generated/gui_generated/src"}) {
        fs::path d = fs::path(touchgfxDir) / sub;
        if (!fs::is_directory(d)) continue;
        for (const auto& e : fs::directory_iterator(d)) {
            const string name = e.path().filename().string();
            if (!e.is_directory() || name.size() < 7 || name.compare(name.size() - 7, 7, "_screen")) continue;
            const string rel = string(sub) + "/" + name + "/";
            bool used = std::any_of(r.files.begin(), r.files.end(), [&](const auto& f) { return f.first.rfind(rel, 0) == 0; });
            if (!used) fs::remove_all(e.path());
        }
    }
    return written;
}
